186: /** Recompute a decision every time. No imported context field grants execution authority. */
187: export function nextAction(task, host) {
188:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
189:   const workflow = definition(task, host.registry, host.inventory);
190:   assert(Object.keys(task.steps).length === workflow.stages.length && workflow.stages.every(s => task.steps[s.id]), 'Task stages differ from Registry');
191:   if (!host.scopeReviewed) return { action: 'evidence_insufficient', reason: 'risk_and_dependency_scope_not_reviewed' };
192:   if (workflow.stages.length > 1 && !host.continuationAuthorized) return { action: 'permission_blocked', reason: 'continuous_workflow_not_authorized' };
193:   if (host.openDecisions?.length) return { action: 'decision_required', skill: 'requirements-clarification', reason: host.openDecisions.join(', ') };
194:   if (host.activeStops?.length) return { action: 'blocked', reason: host.activeStops.join(', ') };
195:   const recovery = recoveryBinding(task, host);
196:   const recoveryCheck = recovery && host.recoveryChecks?.get(recovery);
197:   if (recovery && (!recoveryCheck?.source || recoveryCheck.reconciled !== true)) return { action: 'blocked', reason: 'recovered_execution_state_needs_reconciliation' };
198:   // Unknown effects cannot disappear when an optional predicate or prerequisite changes.
199:   const inflight = workflow.stages.find(stage => ['running', 'interrupted'].includes(task.steps[stage.id].status));
200:   if (inflight) return { stage: inflight.id, skill: inflight.skill, action: 'blocked', reason: 'inflight_operation_needs_reconciliation' };
201:   const uncertain = workflow.stages.find(stage => task.steps[stage.id].effect_state === 'uncertain');
202:   if (uncertain) return { stage: uncertain.id, skill: uncertain.skill, action: 'validation_failed', reason: 'failed_operation_needs_reconciliation' };
203:   const completed = new Set();
204:   for (const stage of workflow.stages) {
205:     const step = task.steps[stage.id];
206:     if (stage.prerequisites.some(id => !completed.has(id))) continue;
207:     if (step.request_binding && step.request_binding !== digest(host.requests?.[stage.id])) {
208:       return { stage: stage.id, skill: stage.skill, action: 'evidence_insufficient', reason: 'operation_scope_changed' };
209:     }
210:     const applies = condition(task, stage.condition, host);
211:     const decision = { stage: stage.id, skill: stage.skill };
212:     const stop = [...(workflow.stop_conditions ?? []), ...stage.stop_conditions]
213:       .find(name => condition(task, name, host) === true);
214:     if (stop) return { ...decision, action: 'blocked', reason: `stop_condition:${stop}` };
215:     if (applies === undefined) return { ...decision, action: 'evidence_insufficient', reason: `condition_unknown:${stage.condition}` };
216:     if (!applies) {
217:       if (!stage.optional) return { ...decision, action: 'evidence_insufficient', reason: `required_condition_false:${stage.condition}` };
218:       // Applicability must not erase a completed operation or its known effects.
219:       if (['completed', 'reused'].includes(step.status)) { completed.add(stage.id); continue; }
220:       if (step.status !== 'skipped' || step.condition_binding !== digest(host.conditions[stage.condition])) return { ...decision, action: 'skip', reason: `not_applicable:${stage.condition}` };

221:       completed.add(stage.id); continue;
222:     }
223:     if (stage.type === 'gate') {
224:       const children = workflow.stages.filter(s => s.approval_gate === stage.id);
225:       if (!children.length) return { ...decision, action: 'permission_blocked', reason: 'gate_has_no_consumer' };
226:       for (const child of children) {
227:         const denied = permission(child.skill, child, task, host);
228:         if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
229:       }
230:       // Always re-evaluate gates against host grants, never reuse persisted approval.
231:       if (step.status !== 'completed') return { ...decision, action: 'approve', reason: 'existing_scoped_host_authorization' };
232:       completed.add(stage.id); continue;
233:     }
234:     const denied = permission(stage.skill, stage, task, host);
235:     if (denied) return { ...decision, action: 'permission_blocked', reason: denied };
236:     if (['completed', 'reused'].includes(step.status) && stepEvidence(task, stage, host)) {
237:       completed.add(stage.id); continue;
238:     }
239:     const failure = step.status === 'validation_failed';
240:     if (failure) return { ...decision, action: 'validation_failed', reason: step.reason || 'explicit_retry_required' };
241:     // Risk checks are additive obligations referencing existing Skills, not new workflows.
242:     if (writes(stage, host)) {
243:       const gap = (host.risks ?? []).flatMap(r => host.registry.coordination?.risk_requirements?.[r]?.before_write ?? [{ claim: `unclassified-risk:${r}` }])
244:         .find(r => !requirement(task, r, host));
245:       if (gap) return { ...decision, action: 'risk_check', requirement: gap, reason: 'risk_requires_additional_evidence' };
246:     }
247:     const candidate = host.reuse?.[stage.id];
248:     if (candidate) {
249:       const provisional = copy(task); provisional.steps[stage.id].evidence_ids = candidate;
250:       if (stepEvidence(provisional, stage, host)) return { ...decision, action: 'reuse', evidence_ids: candidate, reason: 'valid_existing_result' };
251:     }
252:     if ((writes(stage, host) || step.effect_state === 'known' || host.requests[stage.id].capabilities.some(c => c !== 'read_files')) && ['completed', 'reused'].includes(step.status)) {
253:       return { ...decision, action: 'blocked', reason: 'stale_write_result_needs_reconciliation' };
254:     }
255:     return { ...decision, action: 'execute', reason: ['completed', 'reused'].includes(step.status) ? 'prior_evidence_stale_or_unknown' : 'applicable_stage', mode: host.execution === 'same_agent' ? 'same_agent' : 'manual_handoff' };
256:   }
257:   if (completed.size !== workflow.stages.length) return { action: 'evidence_insufficient', reason: 'unresolved_dependencies' };
258:   const obligations = [
259:     ...task.acceptance.map(id => ({ claim: `acceptance:${id}` })),
260:     ...([...completed].some(id => {
261:       const stage = workflow.stages.find(s => s.id === id);
262:       return task.steps[id].status !== 'skipped'
263:         && ['feature-implementation', 'safe-fix-implementation', 'safe-test-implementation'].includes(stage.skill);
264:     }) ? [{ claim: 'behavior-validation', kind: 'test' }] : []),
265:     ...(host.deliveryRequirements ?? []),
266:     ...(host.risks ?? []).flatMap(r => {
267:       const rules = host.registry.coordination?.risk_requirements?.[r];
268:       return rules ? [...rules.before_write, ...rules.before_delivery] : [{ claim: `unclassified-risk:${r}` }];
269:     }),
270:   ];
271:   const missing = obligations.filter(r => !requirement(task, r, host));
272:   if (task.unresolved.length || missing.length) return { action: 'evidence_insufficient', reason: 'delivery_not_proven', missing };
273:   return { action: 'complete', reason: 'applicable_stages_and_acceptance_proven', release_authorized: false };
274: }
