281: export function advance(task, host) {
282:   const action = nextAction(task, host);
283:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
284:     const step = task.steps[action.stage];
285:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
286:     step.reason = action.reason;
287:     if (['execute', 'reuse'].includes(action.action)) step.request_binding = digest(host.requests[action.stage]);
288:     if (action.action === 'execute') {
289:       step.attempts++;
290:       step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'uncertain' : 'none';
291:     }
292:     if (action.action === 'skip') {
293:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
294:       step.condition_binding = digest(host.conditions[stage.condition]);
295:     }
296:     if (action.action === 'reuse') step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'known' : 'none';
297:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
298:     event(task, action.stage, step.status, action.reason);
299:   }
300:   task.next_actions = [action];
301:   return action;
302: }
