304: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
305:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
306:   const step = task.steps[stageId];
307:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
308:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
309:   const denied = permission(stage.skill, stage, task, host);
310:   assert(!denied, denied);
311:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
312:   else {
313:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
314:     assert(stepEvidence(provisional, stage, host), 'Completion requires valid, scoped evidence and independent review');
315:     step.evidence_ids = [...evidenceIds]; step.status = 'completed'; step.effect_state = step.effect_state === 'none' ? 'none' : 'known';
316:   }
317:   event(task, stageId, step.status, failureReason || 'observed_completion');
318: }
