320: /** Reopening is an explicit host decision; only descendants are reopened.
321:  * Evidence is retained, so still-valid independent checks can be reused.
322:  */
323: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
324:   assert(reason && source, 'Reopen requires a sourced reason');
325:   const workflow = definition(task, host.registry, host.inventory);
326:   assert(task.steps[stageId], 'Unknown stage');
327:   const affected = new Set([stageId]);
328:   let changed = true;
329:   while (changed) { changed = false; for (const stage of workflow.stages) {
330:     if (!affected.has(stage.id) && stage.prerequisites.some(id => affected.has(id))) { affected.add(stage.id); changed = true; }
331:   } }
332:   for (const id of affected) {
333:     const stage = workflow.stages.find(s => s.id === id);
334:     if (['running', 'interrupted'].includes(task.steps[id].status)
335:         || task.steps[id].effect_state === 'uncertain'
336:         || ((writes(stage, host) || task.steps[id].effect_state === 'known' || host.requests?.[id]?.capabilities?.some(c => c !== 'read_files')) && ['completed', 'reused', 'validation_failed'].includes(task.steps[id].status))) {
337:       assert(safeToRetry && host.reconciled?.has(reconciliationBinding(task, id, host)), 'Unknown side effects must be reconciled before retry');
338:     }
339:   }
340:   for (const id of affected) {
341:     const previous = task.steps[id].request_binding;
342:     task.steps[id].status = 'pending'; task.steps[id].effect_state = 'reconciled';
343:     delete task.steps[id].request_binding;
344:     event(task, id, 'pending', `${reason} (${source})`);
345:     if (previous) task.history.at(-1).previous_request_binding = previous;
346:   }
347: }
