349: export function encodeTask(task) { return JSON.stringify(task, null, 2) + '\n'; }
350: export function restoreTask(serialized, registry, inventory) {
351:   const task = JSON.parse(serialized);
352:   assert(task.schema_version === 2 && task.id && task.goal && Array.isArray(task.acceptance) && task.acceptance.length, 'Invalid Task Context');
353:   assert(Boolean(task.workflow_id) !== Boolean(task.skill_id), 'Choose one registered workflow or one existing Skill');
354:   assert(task.acceptance.every(item => typeof item === 'string' && item.length)
355:     && new Set(task.acceptance).size === task.acceptance.length, 'Invalid acceptance IDs');
356:   const shape = createTask({ id: task.id, goal: task.goal, acceptance: task.acceptance, workflow_id: task.workflow_id, skill_id: task.skill_id }, registry, inventory);
357:   assert(Object.keys(task).every(key => Object.hasOwn(shape, key)) && Object.keys(shape).every(key => Object.hasOwn(task, key)), 'Unexpected or missing Task Context fields');
358:   for (const name of ['decisions', 'risks', 'permission_refs', 'evidence', 'changes', 'unresolved', 'history', 'next_actions']) assert(Array.isArray(task[name]), `Invalid ${name}`);
359:   assert(task.scope && Array.isArray(task.scope.files) && Array.isArray(task.scope.modules) && Array.isArray(task.scope.interfaces), 'Invalid scope');
360:   runtimeTasks.add(task);
361:   const workflow = definition(task, registry, inventory);
362:   assert(task.steps && Object.keys(task.steps).length === workflow.stages.length, 'Invalid step set');
363:   for (const stage of workflow.stages) {
364:     const step = task.steps[stage.id];
365:     assert(step && states.has(step.status) && Number.isInteger(step.attempts) && step.attempts >= 0 && Array.isArray(step.evidence_ids), 'Invalid step state');
366:     if (step.status === 'running') step.status = 'interrupted';
367:   }
368:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
369:   // No grants, trustedEvidence, capabilities, conditions or runtime commands restored.
370:   task.next_actions = [];
371:   recovered.set(task, { checkpoint: digest(task), import_id: randomUUID() });
372:   return task;
373: }
