1: import test from 'node:test';
2: import assert from 'node:assert/strict';
3: import { mkdtempSync, writeFileSync, readFileSync, rmSync, mkdirSync, symlinkSync, cpSync } from 'node:fs';
4: import { tmpdir } from 'node:os';
5: import path from 'node:path';
6: import { spawnSync } from 'node:child_process';
7: import { parseYamlSubset, validateSchema } from './validate-yaml-schemas.mjs';
8: import { discoverSkillInventory } from './validate-workflows.mjs';
9: import { createTask, captureEvidence, evidenceValidity, validationPlan, digest, taskBinding, reviewBinding, nextAction, advance,
10:   finishStep, reopen, recoveryBinding, reconciliationBinding, encodeTask, restoreTask, fingerprint } from '../packs/engineering/repo-doctor/references/workflow-coordination.mjs';
