12: const registry = parseYamlSubset(readFileSync('packs/engineering/repo-doctor/workflows.yaml', 'utf8'));
13: const inventory = discoverSkillInventory(process.cwd());
14: function setup(t, selector = { skill_id: 'documentation-sync' }) {
15:   const root = mkdtempSync(path.join(tmpdir(), 'rd-coordination-'));
16:   t.after(() => rmSync(root, { recursive: true, force: true }));
17:   for (const name of ['src', 'tests', 'snapshots']) mkdirSync(path.join(root, name));
